			State:     ReasoningEffortStateInvalid,
			Source:    source,
			Requested: requested,
			Supported: supported,
			Reason:    "invalid reasoning_effort " + requested + "; valid values are none, minimal, low, medium, high, xhigh",
		}
	}

	state := ReasoningEffortStateOverride

